#include "target-record.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(int argc,char**argv){unsigned char payload[12288],owner[8193];size_t n,m;FILE*f;struct cl_target_request q;assert(argc==3);f=fopen(argv[1],"rb");assert(f);n=fread(payload,1,sizeof(payload),f);fclose(f);f=fopen(argv[2],"rb");assert(f);m=fread(owner,1,sizeof(owner),f);fclose(f);assert(cl_target_parse(payload,n,&q));assert(cl_target_owner_record(owner,m,&q,99,"11111111:0000000000000011","22222222:0000000000000022"));assert(!cl_target_owner_record(owner,m,&q,100,"11111111:0000000000000011","22222222:0000000000000022"));assert(!cl_target_owner_record(owner,m,&q,99,"11111111:0000000000000012","22222222:0000000000000022"));payload[19]='f';assert(!cl_target_owner_record(owner,m,&q,99,"11111111:0000000000000011","22222222:0000000000000022"));payload[19]='e';q.epoch++;assert(!cl_target_owner_record(owner,m,&q,99,"11111111:0000000000000011","22222222:0000000000000022"));q.epoch--;assert(!cl_target_owner_record(owner,m-1,&q,99,"11111111:0000000000000011","22222222:0000000000000022"));assert(cl_target_epoch_record((const unsigned char*)"{\"epoch\":3}\n",12,3));assert(!cl_target_epoch_record((const unsigned char*)"{\"epoch\":3,\"epoch\":3}\n",22,3));assert(!cl_target_epoch_record((const unsigned char*)"{\"epoch\":03}\n",13,3));puts("native target lease record controls PASS");return 0;}
